package idl

import (
	"fmt"
	"go/format"
	"strings"
)

// GoPath is the committed host-side Go generated file, relative to the module
// root.
const GoPath = "domain/plugin/abi/abi_gen.go"

// RustPath is the committed Rust generated file, relative to the module root.
const RustPath = "sdk/rust/src/abi_v1.rs"

// serviceCallFunction is the wire name of the one function every service
// module exports. The generated Rust extern keeps a distinct Rust-side name so
// it cannot collide with the typed `call` wrapper, and binds it to this wasm
// import field with link_name.
const serviceCallFunction = "call"

// GenerateGo renders the host-side Go types for the IDL.
func (d *Definition) GenerateGo() []byte {
	var out strings.Builder
	fmt.Fprintf(&out, "// Code generated by sdk/idl/gen from sdk/idl/natcatty_v1.idl; DO NOT EDIT.\n\n")
	fmt.Fprintf(&out, "// Package abi contains the host-side plugin ABI types, module names, and\n")
	fmt.Fprintf(&out, "// function descriptors generated from the versioned Natcatty IDL.\n")
	fmt.Fprintf(&out, "package abi\n\n")
	fmt.Fprintf(&out, "import (\n\t\"fmt\"\n\t\"strings\"\n)\n\n")
	fmt.Fprintf(&out, "// IDL identity and wire version.\nconst (\n")
	fmt.Fprintf(&out, "\tIDLName    = %q\n", d.Name)
	fmt.Fprintf(&out, "\tIDLVersion = %q\n", d.Version)
	fmt.Fprintf(&out, "\t// Version is the wire ABI major the host and its bindings speak.\n")
	fmt.Fprintf(&out, "\tVersion = %d\n", d.ABI)
	fmt.Fprintf(&out, ")\n\n")

	for _, enum := range d.Enums {
		goType := goScalar(enum.Base)
		fmt.Fprintf(&out, "// %s is the generated %s enum.\ntype %s %s\n\n", enum.Name, enum.Name, enum.Name, goType)
		fmt.Fprintf(&out, "const (\n")
		for _, value := range enum.Values {
			fmt.Fprintf(&out, "\t%s%s %s = %d\n", enum.Name, goCamel(value.Name), enum.Name, value.Value)
		}
		fmt.Fprintf(&out, ")\n\n")
		fmt.Fprintf(&out, "// Valid reports whether v is a declared %s value.\n", enum.Name)
		fmt.Fprintf(&out, "func (v %s) Valid() bool {\n\tswitch v {\n\tcase ", enum.Name)
		for i, value := range enum.Values {
			if i > 0 {
				fmt.Fprintf(&out, ", ")
			}
			fmt.Fprintf(&out, "%s%s", enum.Name, goCamel(value.Name))
		}
		fmt.Fprintf(&out, ":\n\t\treturn true\n\t}\n\treturn false\n}\n\n")
		fmt.Fprintf(&out, "// String renders the IDL name of v.\n")
		fmt.Fprintf(&out, "func (v %s) String() string {\n\tswitch v {\n", enum.Name)
		for _, value := range enum.Values {
			fmt.Fprintf(&out, "\tcase %s%s:\n\t\treturn %q\n", enum.Name, goCamel(value.Name), value.Name)
		}
		fmt.Fprintf(&out, "\t}\n\treturn fmt.Sprintf(\"level(%%d)\", int64(v))\n}\n\n")
	}

	for _, record := range d.Records {
		fmt.Fprintf(&out, "// %s is the generated %s record.\ntype %s struct {\n", record.Name, record.Name, record.Name)
		for _, field := range record.Fields {
			fmt.Fprintf(&out, "\t%s %s\n", goCamel(field.Name), goScalar(field.Type))
		}
		fmt.Fprintf(&out, "}\n\n")
	}

	for _, handle := range d.Handles {
		fmt.Fprintf(&out, "// %s is an opaque generation-tagged host-owned resource.\n", handle.Name)
		fmt.Fprintf(&out, "type %s %s\n\n", handle.Name, goScalar(handle.Base))
		fmt.Fprintf(&out, "// Slot returns the 1-based table slot encoded in h.\n")
		fmt.Fprintf(&out, "func (h %s) Slot() uint32 { return uint32(h) }\n\n", handle.Name)
		fmt.Fprintf(&out, "// Generation returns the generation encoded in h.\n")
		fmt.Fprintf(&out, "func (h %s) Generation() uint32 { return uint32(h >> 32) }\n\n", handle.Name)
	}

	fmt.Fprintf(&out, "// Param is one generated function parameter.\ntype Param struct {\n\tName string\n\tType string\n}\n\n")
	fmt.Fprintf(&out, "// Function is one generated host import signature.\ntype Function struct {\n\tName   string\n\tParams []Param\n\tResult string\n}\n\n")
	fmt.Fprintf(&out, "// GuestExport is one generated guest export signature.\ntype GuestExport struct {\n\tName     string\n\tWire     string\n\tParams   []Param\n\tResult   string\n\tOptional bool\n}\n\n")

	host := d.HostModule()
	fmt.Fprintf(&out, "// HostModuleName is the imported module for the v1 ABI.\nconst HostModuleName = %q\n\n", host.Name)
	fmt.Fprintf(&out, "// Host import names.\nconst (\n")
	for _, function := range host.Functions {
		fmt.Fprintf(&out, "\tHostFunction%s = %q\n", goCamel(function.Name), function.Name)
	}
	fmt.Fprintf(&out, ")\n\n")
	fmt.Fprintf(&out, "// HostFunctions lists every function a v1 module may import.\nvar HostFunctions = []Function{\n")
	for _, function := range host.Functions {
		fmt.Fprintf(&out, "\t{Name: %q, Params: %s, Result: %q},\n",
			function.Name, goParams(function.Params), function.Result)
	}
	fmt.Fprintf(&out, "}\n\n")
	writeServices(&out, d)

	fmt.Fprintf(&out, "// HostFunction returns the generated signature for a permitted import.\n")
	fmt.Fprintf(&out, "// Every service module imports exactly one function, ServiceCallFunction.\n")
	fmt.Fprintf(&out, "func HostFunction(module, name string) (Function, bool) {\n")
	fmt.Fprintf(&out, "\tif module == HostModuleName {\n")
	fmt.Fprintf(&out, "\t\tfor _, function := range HostFunctions {\n")
	fmt.Fprintf(&out, "\t\t\tif function.Name == name {\n\t\t\t\treturn function, true\n\t\t\t}\n\t\t}\n")
	fmt.Fprintf(&out, "\t\treturn Function{}, false\n\t}\n")
	fmt.Fprintf(&out, "\tif name == ServiceCallFunction && IsServiceModule(module) {\n")
	fmt.Fprintf(&out, "\t\treturn ServiceCallSignature, true\n\t}\n")
	fmt.Fprintf(&out, "\treturn Function{}, false\n}\n\n")
	fmt.Fprintf(&out, "// AllowsHostImport reports whether module/name is in the v1 import allowlist.\n")
	fmt.Fprintf(&out, "func AllowsHostImport(module, name string) bool {\n")
	fmt.Fprintf(&out, "\t_, ok := HostFunction(module, name)\n\treturn ok\n}\n\n")

	guest := d.GuestModule()
	fmt.Fprintf(&out, "// Guest module export names.\nconst (\n")
	for _, export := range guest.Exports {
		fmt.Fprintf(&out, "\tExport%s = %q\n", goCamel(export.Name), export.Wire)
	}
	fmt.Fprintf(&out, ")\n\n")
	fmt.Fprintf(&out, "// GuestExports lists the reactor exports the host understands.\nvar GuestExports = []GuestExport{\n")
	for _, export := range guest.Exports {
		fmt.Fprintf(&out, "\t{Name: %q, Wire: %q, Params: %s, Result: %q, Optional: %t},\n",
			export.Name, export.Wire, goParams(export.Params), export.Result, export.Optional)
	}
	fmt.Fprintf(&out, "}\n\n")
	fmt.Fprintf(&out, "// GuestExportByName returns the generated signature for a permitted export.\n")
	fmt.Fprintf(&out, "func GuestExportByName(name string) (GuestExport, bool) {\n")
	fmt.Fprintf(&out, "\tfor _, export := range GuestExports {\n\t\tif export.Wire == name {\n\t\t\treturn export, true\n\t\t}\n\t}\n\treturn GuestExport{}, false\n}\n\n")

	writeWASMTypes(&out, d)

	fmt.Fprintf(&out, "// ABIMismatchError reports a module built for a different wire ABI.\ntype ABIMismatchError struct {\n\tWant int\n\tGot  int\n}\n\n")
	fmt.Fprintf(&out, "func (e *ABIMismatchError) Error() string {\n")
	fmt.Fprintf(&out, "\treturn fmt.Sprintf(\"plugin ABI %%d is not supported (host supports %%d)\", e.Got, e.Want)\n}\n\n")
	fmt.Fprintf(&out, "// CheckABIVersion rejects a wire ABI this generated host code cannot speak.\n")
	fmt.Fprintf(&out, "func CheckABIVersion(got int) error {\n")
	fmt.Fprintf(&out, "\tif got != Version {\n\t\treturn &ABIMismatchError{Want: Version, Got: got}\n\t}\n\treturn nil\n}\n")
	// The committed file must satisfy the repository's gofmt gate.
	if formatted, err := format.Source([]byte(out.String())); err == nil {
		return formatted
	}
	return []byte(out.String())
}

// GenerateRust renders the guest-side Rust bindings for the IDL.
func (d *Definition) GenerateRust() []byte {
	var out strings.Builder
	fmt.Fprintf(&out, "// Code generated by sdk/idl/gen from sdk/idl/natcatty_v1.idl; DO NOT EDIT.\n\n")
	fmt.Fprintf(&out, "//! Generated host bindings for the Natcatty plugin ABI.\n\n")
	fmt.Fprintf(&out, "pub const IDL_NAME: &str = %q;\n", d.Name)
	fmt.Fprintf(&out, "pub const IDL_VERSION: &str = %q;\n", d.Version)
	fmt.Fprintf(&out, "pub const ABI_VERSION: i32 = %d;\n\n", d.ABI)

	for _, enum := range d.Enums {
		rustBase := rustEnumBase(enum.Base)
		fmt.Fprintf(&out, "#[repr(%s)]\n", enum.Base)
		fmt.Fprintf(&out, "#[derive(Clone, Copy, Debug, PartialEq, Eq)]\n")
		fmt.Fprintf(&out, "pub enum %s {\n", enum.Name)
		for _, value := range enum.Values {
			fmt.Fprintf(&out, "    %s = %d,\n", goCamel(value.Name), value.Value)
		}
		fmt.Fprintf(&out, "}\n\n")
		fmt.Fprintf(&out, "impl %s {\n", enum.Name)
		fmt.Fprintf(&out, "    /// Returns the enum for one wire value.\n")
		fmt.Fprintf(&out, "    pub const fn from_code(code: %s) -> Option<Self> {\n", rustBase)
		fmt.Fprintf(&out, "        match code {\n")
		for _, value := range enum.Values {
			fmt.Fprintf(&out, "            %d => Some(Self::%s),\n", value.Value, goCamel(value.Name))
		}
		fmt.Fprintf(&out, "            _ => None,\n        }\n    }\n\n")
		fmt.Fprintf(&out, "    /// Returns the wire value of this enum.\n")
		fmt.Fprintf(&out, "    pub const fn code(self) -> %s { self as %s }\n", rustBase, rustBase)
		fmt.Fprintf(&out, "}\n\n")
	}

	for _, record := range d.Records {
		fmt.Fprintf(&out, "#[repr(C)]\n#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]\n")
		fmt.Fprintf(&out, "pub struct %s {\n", record.Name)
		for _, field := range record.Fields {
			fmt.Fprintf(&out, "    pub %s: %s,\n", rustIdent(field.Name), field.Type)
		}
		fmt.Fprintf(&out, "}\n\n")
	}

	for _, handle := range d.Handles {
		fmt.Fprintf(&out, "#[repr(transparent)]\n#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]\n")
		fmt.Fprintf(&out, "pub struct %s(pub %s);\n\n", handle.Name, handle.Base)
		fmt.Fprintf(&out, "impl %s {\n", handle.Name)
		fmt.Fprintf(&out, "    /// Returns the 1-based table slot encoded in the handle.\n")
		fmt.Fprintf(&out, "    pub const fn slot(self) -> u32 { self.0 as u32 }\n\n")
		fmt.Fprintf(&out, "    /// Returns the generation encoded in the handle.\n")
		fmt.Fprintf(&out, "    pub const fn generation(self) -> u32 { (self.0 >> 32) as u32 }\n")
		fmt.Fprintf(&out, "}\n\n")
	}

	fmt.Fprintf(&out, "/// One host-service call result. The payload points into the caller's\n")
	fmt.Fprintf(&out, "/// response buffer and is empty unless the transport status is zero.\n")
	fmt.Fprintf(&out, "#[derive(Clone, Copy, Debug, PartialEq, Eq)]\n")
	fmt.Fprintf(&out, "pub struct ServiceReply<'a> {\n")
	fmt.Fprintf(&out, "    /// The transport status returned by the service module.\n")
	fmt.Fprintf(&out, "    pub status: i32,\n")
	fmt.Fprintf(&out, "    /// The bytes the host copied into the response buffer.\n")
	fmt.Fprintf(&out, "    pub payload: &'a [u8],\n")
	fmt.Fprintf(&out, "}\n\n")
	fmt.Fprintf(&out, "impl<'a> ServiceReply<'a> {\n")
	fmt.Fprintf(&out, "    /// Reports whether the call completed at the transport layer.\n")
	fmt.Fprintf(&out, "    pub const fn is_ok(self) -> bool { self.status == 0 }\n\n")
	fmt.Fprintf(&out, "    /// Returns the typed transport status, or None for an unknown code.\n")
	fmt.Fprintf(&out, "    pub const fn transport(self) -> Option<ServiceStatus> {\n")
	fmt.Fprintf(&out, "        ServiceStatus::from_code(self.status)\n")
	fmt.Fprintf(&out, "    }\n}\n\n")

	host := d.HostModule()
	fmt.Fprintf(&out, "#[cfg(target_arch = \"wasm32\")]\n")
	fmt.Fprintf(&out, "mod raw {\n")
	fmt.Fprintf(&out, "    #[link(wasm_import_module = %q)]\n", host.Name)
	fmt.Fprintf(&out, "    extern \"C\" {\n")
	for _, function := range host.Functions {
		fmt.Fprintf(&out, "        pub fn %s(%s)%s;\n",
			rustIdent(function.Name), rustRawParams(function.Params), rustRawResult(function.Result))
	}
	fmt.Fprintf(&out, "    }\n}\n\n")
	writeRustHostShim(&out)

	writeRustHelpers(&out, host)

	if len(d.Services) > 0 {
		fmt.Fprintf(&out, "/// Host-service import modules. Each exposes one `call` entry and stable\n")
		fmt.Fprintf(&out, "/// method ids; payloads are opaque request and response bytes.\n")
		fmt.Fprintf(&out, "pub mod service {\n")
		fmt.Fprintf(&out, "    /// The single exported function of every service module.\n")
		fmt.Fprintf(&out, "    pub const CALL: &str = %q;\n\n", serviceCallFunction)
		for _, service := range d.Services {
			fmt.Fprintf(&out, "    pub mod %s {\n", rustIdent(service.Name))
			fmt.Fprintf(&out, "        pub const NAME: &str = %q;\n", service.Name)
			fmt.Fprintf(&out, "        pub const MODULE: &str = %q;\n", service.Module())
			for _, method := range service.Methods {
				fmt.Fprintf(&out, "        pub const METHOD_%s: u32 = %d;\n",
					rustConstSuffix(method.Name), method.ID)
			}
			fmt.Fprintf(&out, "\n        #[cfg(target_arch = \"wasm32\")]\n")
			fmt.Fprintf(&out, "        #[link(wasm_import_module = %q)]\n", service.Module())
			fmt.Fprintf(&out, "        extern \"C\" {\n")
			// The wasm import field is the function name the host exports:
			// `call`. Without link_name Rust would import the Rust-side alias
			// `host_call`, which the structural allowlist rejects.
			fmt.Fprintf(&out, "            #[link_name = %q]\n", serviceCallFunction)
			fmt.Fprintf(&out, "            fn host_call(method_id: u32, req_ptr: u32, req_len: u32, resp_ptr: u32, resp_cap: u32) -> i32;\n")
			fmt.Fprintf(&out, "        }\n\n")
			fmt.Fprintf(&out, "        /// Calls one method with a request and fills the caller's response buffer.\n")
			fmt.Fprintf(&out, "        pub fn call_method(method_id: u32, request: &[u8], response: &mut [u8]) -> i32 {\n")
			fmt.Fprintf(&out, "            #[cfg(target_arch = \"wasm32\")]\n")
			fmt.Fprintf(&out, "            {\n")
			fmt.Fprintf(&out, "                unsafe {\n")
			fmt.Fprintf(&out, "                    host_call(method_id, request.as_ptr() as u32, request.len() as u32,\n")
			fmt.Fprintf(&out, "                         response.as_mut_ptr() as u32, response.len() as u32)\n")
			fmt.Fprintf(&out, "                }\n            }\n")
			fmt.Fprintf(&out, "            #[cfg(not(target_arch = \"wasm32\"))]\n")
			fmt.Fprintf(&out, "            {\n")
			fmt.Fprintf(&out, "                super::super::host::with(|host| {\n")
			fmt.Fprintf(&out, "                    host.service_call(NAME, method_id, request, response)\n")
			fmt.Fprintf(&out, "                })\n")
			fmt.Fprintf(&out, "                .unwrap_or(super::super::ServiceStatus::Unavailable.code())\n")
			fmt.Fprintf(&out, "            }\n        }\n\n")
			fmt.Fprintf(&out, "        /// Calls one method and returns the transport status with the\n")
			fmt.Fprintf(&out, "        /// response bytes the host copied.\n")
			fmt.Fprintf(&out, "        pub fn call<'a>(method_id: u32, request: &[u8], response: &'a mut [u8])\n")
			fmt.Fprintf(&out, "            -> super::super::ServiceReply<'a> {\n")
			fmt.Fprintf(&out, "            let status = call_method(method_id, request, response);\n")
			fmt.Fprintf(&out, "            let length = if status == 0 {\n")
			fmt.Fprintf(&out, "                let declared = super::super::service_response_len() as usize;\n")
			fmt.Fprintf(&out, "                declared.min(response.len())\n")
			fmt.Fprintf(&out, "            } else {\n")
			fmt.Fprintf(&out, "                0\n            };\n")
			fmt.Fprintf(&out, "            super::super::ServiceReply { status, payload: &response[..length] }\n")
			fmt.Fprintf(&out, "        }\n")
			for _, method := range service.Methods {
				wrapper := rustIdent(method.Name)
				if wrapper == "call" {
					wrapper = "call_method_named"
				}
				fmt.Fprintf(&out, "\n        /// Calls `%s.%s`.\n", service.Name, method.Name)
				fmt.Fprintf(&out, "        pub fn %s<'a>(request: &[u8], response: &'a mut [u8])\n", wrapper)
				fmt.Fprintf(&out, "            -> super::super::ServiceReply<'a> {\n")
				fmt.Fprintf(&out, "            call(METHOD_%s, request, response)\n", rustConstSuffix(method.Name))
				fmt.Fprintf(&out, "        }\n")
			}
			fmt.Fprintf(&out, "    }\n\n")
		}
		fmt.Fprintf(&out, "}\n\n")
	}

	guest := d.GuestModule()
	fmt.Fprintf(&out, "// Guest export names.\n")
	for _, export := range guest.Exports {
		fmt.Fprintf(&out, "pub const EXPORT_%s: &str = %q;\n", rustConstSuffix(export.Name), export.Wire)
	}
	fmt.Fprintf(&out, "\n")

	fmt.Fprintf(&out, "/// Returned when the host speaks a different wire ABI.\n")
	fmt.Fprintf(&out, "#[derive(Clone, Copy, Debug, PartialEq, Eq)]\n")
	fmt.Fprintf(&out, "pub enum AbiMismatch {\n")
	fmt.Fprintf(&out, "    /// The host's ABI version, which these bindings do not support.\n")
	fmt.Fprintf(&out, "    HostAbi(i32),\n")
	fmt.Fprintf(&out, "    /// The guest's ABI version, which the host does not support.\n")
	fmt.Fprintf(&out, "    GuestAbi(i32),\n")
	fmt.Fprintf(&out, "}\n\n")
	fmt.Fprintf(&out, "impl core::fmt::Display for AbiMismatch {\n")
	fmt.Fprintf(&out, "    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {\n")
	fmt.Fprintf(&out, "        match *self {\n")
	fmt.Fprintf(&out, "            AbiMismatch::HostAbi(host) => {\n")
	fmt.Fprintf(&out, "                write!(f, \"plugin ABI {} is not supported (bindings speak {})\", host, ABI_VERSION)\n")
	fmt.Fprintf(&out, "            }\n")
	fmt.Fprintf(&out, "            AbiMismatch::GuestAbi(guest) => {\n")
	fmt.Fprintf(&out, "                write!(f, \"guest ABI {} is not supported (host speaks {})\", guest, ABI_VERSION)\n")
	fmt.Fprintf(&out, "            }\n")
	fmt.Fprintf(&out, "        }\n")
	fmt.Fprintf(&out, "    }\n")
	fmt.Fprintf(&out, "}\n\n")
	fmt.Fprintf(&out, "impl std::error::Error for AbiMismatch {}\n\n")
	fmt.Fprintf(&out, "/// Checks the host ABI before the guest does any work. Call this from\n")
	fmt.Fprintf(&out, "/// `natcatty_init` and fail init when it returns an error.\n")
	fmt.Fprintf(&out, "pub fn ensure_compatible_abi() -> Result<(), AbiMismatch> {\n")
	fmt.Fprintf(&out, "    let host = abi_version();\n")
	fmt.Fprintf(&out, "    if host == ABI_VERSION {\n")
	fmt.Fprintf(&out, "        Ok(())\n")
	fmt.Fprintf(&out, "    } else {\n")
	fmt.Fprintf(&out, "        Err(AbiMismatch::HostAbi(host))\n")
	fmt.Fprintf(&out, "    }\n")
	fmt.Fprintf(&out, "}\n\n")
	fmt.Fprintf(&out, "/// The guest export the host reads before calling init.\n")
	fmt.Fprintf(&out, "#[no_mangle]\n")
	fmt.Fprintf(&out, "pub extern \"C\" fn natcatty_abi_version() -> i32 {\n")
	fmt.Fprintf(&out, "    ABI_VERSION\n")
	fmt.Fprintf(&out, "}\n")
	return []byte(out.String())
}

// writeServices emits the host-service module names, stable method IDs, and
// the single call signature every service module exports. Service payloads
// travel as opaque request/response bytes, so adding a method is a minor
// change that leaves every existing import untouched.
func writeServices(out *strings.Builder, d *Definition) {
	fmt.Fprintf(out, "// ServiceCallFunction is the single exported function of every service module.\n")
	fmt.Fprintf(out, "const ServiceCallFunction = %q\n\n", serviceCallFunction)
	fmt.Fprintf(out, "// ServiceCallSignature is the wire signature shared by every service module.\n")
	fmt.Fprintf(out, "var ServiceCallSignature = Function{Name: ServiceCallFunction, Params: []Param{\n")
	fmt.Fprintf(out, "\t{Name: \"method_id\", Type: \"u32\"},\n")
	fmt.Fprintf(out, "\t{Name: \"req_ptr\", Type: \"u32\"},\n")
	fmt.Fprintf(out, "\t{Name: \"req_len\", Type: \"u32\"},\n")
	fmt.Fprintf(out, "\t{Name: \"resp_ptr\", Type: \"u32\"},\n")
	fmt.Fprintf(out, "\t{Name: \"resp_cap\", Type: \"u32\"},\n")
	fmt.Fprintf(out, "}, Result: \"i32\"}\n\n")
	fmt.Fprintf(out, "// ServiceMethod is one stable method id within a service module.\n")
	fmt.Fprintf(out, "type ServiceMethod struct {\n\tName string\n\tID   uint32\n}\n\n")
	fmt.Fprintf(out, "// Service is one host-service import module.\n")
	fmt.Fprintf(out, "type Service struct {\n\tName    string\n\tModule  string\n\tMethods []ServiceMethod\n}\n\n")
	fmt.Fprintf(out, "// Host service module names and stable method ids.\nconst (\n")
	for _, service := range d.Services {
		camel := goCamel(service.Name)
		fmt.Fprintf(out, "\tService%s = %q\n", camel, service.Name)
		fmt.Fprintf(out, "\tService%sModule = %q\n", camel, service.Module())
		for _, method := range service.Methods {
			fmt.Fprintf(out, "\t%sMethod%s uint32 = %d\n", camel, goCamel(method.Name), method.ID)
		}
	}
	fmt.Fprintf(out, ")\n\n")
	fmt.Fprintf(out, "// Services lists every host-service module in the v1 ABI.\n")
	fmt.Fprintf(out, "var Services = []Service{\n")
	for _, service := range d.Services {
		fmt.Fprintf(out, "\t{Name: %q, Module: %q, Methods: []ServiceMethod{\n", service.Name, service.Module())
		for _, method := range service.Methods {
			fmt.Fprintf(out, "\t\t{Name: %q, ID: %d},\n", method.Name, method.ID)
		}
		fmt.Fprintf(out, "\t}},\n")
	}
	fmt.Fprintf(out, "}\n\n")
	fmt.Fprintf(out, "// ServiceByName returns a service by its symbolic name.\n")
	fmt.Fprintf(out, "func ServiceByName(name string) (Service, bool) {\n")
	fmt.Fprintf(out, "\tfor _, service := range Services {\n\t\tif service.Name == name {\n\t\t\treturn service, true\n\t\t}\n\t}\n\treturn Service{}, false\n}\n\n")
	fmt.Fprintf(out, "// ServiceByModule returns a service by its WebAssembly import module.\n")
	fmt.Fprintf(out, "func ServiceByModule(module string) (Service, bool) {\n")
	fmt.Fprintf(out, "\tfor _, service := range Services {\n\t\tif service.Module == module {\n\t\t\treturn service, true\n\t\t}\n\t}\n\treturn Service{}, false\n}\n\n")
	fmt.Fprintf(out, "// IsServiceModule reports whether module is one of the declared service modules.\n")
	fmt.Fprintf(out, "func IsServiceModule(module string) bool {\n")
	fmt.Fprintf(out, "\t_, ok := ServiceByModule(module)\n\treturn ok\n}\n\n")
	fmt.Fprintf(out, "// ServiceMethodByID returns one method within a service.\n")
	fmt.Fprintf(out, "func ServiceMethodByID(serviceName string, id uint32) (ServiceMethod, bool) {\n")
	fmt.Fprintf(out, "\tservice, ok := ServiceByName(serviceName)\n")
	fmt.Fprintf(out, "\tif !ok {\n\t\treturn ServiceMethod{}, false\n\t}\n")
	fmt.Fprintf(out, "\tfor _, method := range service.Methods {\n\t\tif method.ID == id {\n\t\t\treturn method, true\n\t\t}\n\t}\n\treturn ServiceMethod{}, false\n}\n\n")
	fmt.Fprintf(out, "// ServiceMethodByName returns one method within a service by name.\n")
	fmt.Fprintf(out, "func ServiceMethodByName(serviceName, name string) (ServiceMethod, bool) {\n")
	fmt.Fprintf(out, "\tservice, ok := ServiceByName(serviceName)\n")
	fmt.Fprintf(out, "\tif !ok {\n\t\treturn ServiceMethod{}, false\n\t}\n")
	fmt.Fprintf(out, "\tfor _, method := range service.Methods {\n\t\tif method.Name == name {\n\t\t\treturn method, true\n\t\t}\n\t}\n\treturn ServiceMethod{}, false\n}\n\n")
}

// writeWASMTypes emits the mapping from IDL types to WebAssembly value types
// and the signature checker shared by the runtime and conformance.
func writeWASMTypes(out *strings.Builder, d *Definition) {
	i32 := []string{"i32", "u32"}
	i64 := []string{"i64", "u64"}
	for _, enum := range d.Enums {
		if enum.Base == "i32" {
			i32 = append(i32, enum.Name)
		} else {
			i64 = append(i64, enum.Name)
		}
	}
	for _, handle := range d.Handles {
		i64 = append(i64, handle.Name)
	}
	out.WriteString("// WebAssembly value type encodings used by generated signatures.\n")
	out.WriteString("const (\n\tWASMTypeI32 byte = 0x7f\n\tWASMTypeI64 byte = 0x7e\n)\n\n")
	out.WriteString("// WASMType maps an IDL type name to its WebAssembly value type. Records\n")
	out.WriteString("// do not cross the ABI by value and have no mapping.\n")
	out.WriteString("func WASMType(typeName string) (byte, bool) {\n\tswitch typeName {\n")
	fmt.Fprintf(out, "\tcase %s:\n\t\treturn WASMTypeI32, true\n", quotedNames(i32))
	fmt.Fprintf(out, "\tcase %s:\n\t\treturn WASMTypeI64, true\n", quotedNames(i64))
	out.WriteString("\t}\n\treturn 0, false\n}\n\n")

	out.WriteString(`// SignatureError reports a module function whose WebAssembly signature does
// not match the generated IDL signature.
type SignatureError struct {
	Function string
	Want     string
	Got      string
}

func (e *SignatureError) Error() string {
	return fmt.Sprintf("%s has signature %s, want %s", e.Function, e.Got, e.Want)
}

// CheckSignature compares observed WebAssembly parameter and result types
// with the generated IDL signature at name. The observed values are
// WebAssembly value type encodings.
func CheckSignature(name string, params []Param, result string, gotParams, gotResults []byte) error {
	wantParams := make([]byte, 0, len(params))
	for _, param := range params {
		wire, ok := WASMType(param.Type)
		if !ok {
			return fmt.Errorf("%s parameter %s uses non-wire type %q", name, param.Name, param.Type)
		}
		wantParams = append(wantParams, wire)
	}
	var wantResult byte
	if result != "" {
		wire, ok := WASMType(result)
		if !ok {
			return fmt.Errorf("%s result uses non-wire type %q", name, result)
		}
		wantResult = wire
	}
	if sameWireTypes(wantParams, gotParams) && sameWireResult(result != "", wantResult, gotResults) {
		return nil
	}
	return &SignatureError{
		Function: name,
		Want:     wantedSignature(params, result),
		Got:      observedSignature(gotParams, gotResults),
	}
}

func sameWireTypes(want, got []byte) bool {
	if len(want) != len(got) {
		return false
	}
	for i := range want {
		if want[i] != got[i] {
			return false
		}
	}
	return true
}

func sameWireResult(wantsResult bool, want byte, got []byte) bool {
	if !wantsResult {
		return len(got) == 0
	}
	return len(got) == 1 && got[0] == want
}

func wantedSignature(params []Param, result string) string {
	parts := make([]string, 0, len(params))
	for _, param := range params {
		parts = append(parts, typeWireName(param.Type))
	}
	signature := "(" + strings.Join(parts, ", ") + ")"
	if result != "" {
		signature += " -> " + typeWireName(result)
	}
	return signature
}

func observedSignature(params, results []byte) string {
	parts := make([]string, 0, len(params))
	for _, param := range params {
		parts = append(parts, wireName(param))
	}
	signature := "(" + strings.Join(parts, ", ") + ")"
	switch len(results) {
	case 0:
	case 1:
		signature += " -> " + wireName(results[0])
	default:
		multi := make([]string, 0, len(results))
		for _, result := range results {
			multi = append(multi, wireName(result))
		}
		signature += " -> (" + strings.Join(multi, ", ") + ")"
	}
	return signature
}

func typeWireName(typeName string) string {
	wire, ok := WASMType(typeName)
	if !ok {
		return typeName
	}
	return wireName(wire)
}

func wireName(wire byte) string {
	switch wire {
	case WASMTypeI32:
		return "i32"
	case WASMTypeI64:
		return "i64"
	}
	return fmt.Sprintf("0x%02x", wire)
}

`)
}

func quotedNames(names []string) string {
	quoted := make([]string, 0, len(names))
	for _, name := range names {
		quoted = append(quoted, fmt.Sprintf("%q", name))
	}
	return strings.Join(quoted, ", ")
}

func goParams(params []Param) string {
	if len(params) == 0 {
		return "nil"
	}
	var parts []string
	for _, param := range params {
		parts = append(parts, fmt.Sprintf("{Name: %q, Type: %q}", param.Name, param.Type))
	}
	return "[]Param{" + strings.Join(parts, ", ") + "}"
}

func goScalar(typ string) string {
	switch typ {
	case "i32":
		return "int32"
	case "u32":
		return "uint32"
	case "i64":
		return "int64"
	case "u64":
		return "uint64"
	default:
		return typ
	}
}

func rustRawParams(params []Param) string {
	if len(params) == 0 {
		return ""
	}
	var parts []string
	for _, param := range params {
		parts = append(parts, fmt.Sprintf("%s: %s", rustIdent(param.Name), rustRawType(param.Type)))
	}
	return strings.Join(parts, ", ")
}

func rustRawResult(result string) string {
	if result == "" {
		return ""
	}
	return " -> " + rustRawType(result)
}

func rustRawType(typ string) string {
	switch typ {
	case "i32", "u32", "i64", "u64":
		return typ
	case "LogLevel", "LanguageKind":
		// Enumerations are laid out as their declared integer base on the
		// wire; the generated Rust enum is not repr(i32)-compatible in an
		// extern signature.
		return "i32"
	default:
		return typ
	}
}

func rustIdent(name string) string {
	if isRustKeyword(name) {
		return name + "_"
	}
	return name
}

func isRustKeyword(name string) bool {
	switch name {
	case "as", "break", "const", "continue", "crate", "else", "enum", "extern",
		"false", "fn", "for", "if", "impl", "in", "let", "loop", "match",
		"mod", "move", "mut", "pub", "ref", "return", "self", "static",
		"struct", "super", "trait", "true", "type", "unsafe", "use", "where",
		"while", "async", "await", "dyn":
		return true
	}
	return false
}

// writeRustHelpers emits the typed Rust wrappers for the host functions with
// an obvious borrowed-slice shape. Each wrapper has one wasm body calling the
// imported function and one native body dispatching to the installed test
// host, so the same generated bindings compile and run under `cargo test`.
func writeRustHelpers(out *strings.Builder, host Host) {
	for _, function := range host.Functions {
		switch function.Name {
		case "abi_version":
			if len(function.Params) == 0 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Returns the host ABI version.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn abi_version() -> i32 { unsafe { raw::abi_version() } }\n\n")
				fmt.Fprintf(out, "/// Returns the host ABI version, or the bindings' ABI when no mock host\n")
				fmt.Fprintf(out, "/// is installed.\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn abi_version() -> i32 {\n")
				fmt.Fprintf(out, "    host::with(|host| host.abi_version()).unwrap_or(ABI_VERSION)\n}\n\n")
			}
		case "now_ns":
			if len(function.Params) == 0 && function.Result == "i64" {
				fmt.Fprintf(out, "/// Returns the host clock in Unix nanoseconds.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn now_ns() -> i64 { unsafe { raw::now_ns() } }\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn now_ns() -> i64 { host::with(|host| host.now_ns()).unwrap_or(0) }\n\n")
			}
		case "log":
			if len(function.Params) == 3 && function.Result == "" &&
				function.Params[1].Type == "u32" && function.Params[2].Type == "u32" {
				levelType := function.Params[0].Type
				fmt.Fprintf(out, "/// Writes one bounded log line through the host.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn log(level: %s, message: &[u8]) {\n", levelType)
				fmt.Fprintf(out, "    unsafe { raw::log(level as i32, message.as_ptr() as u32, message.len() as u32) }\n}\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn log(level: %s, message: &[u8]) {\n", levelType)
				fmt.Fprintf(out, "    let _ = host::with(|host| host.log(level as i32, message));\n}\n\n")
			}
		case "random_get":
			if len(function.Params) == 2 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Fills the buffer with host random bytes.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn random_get(buffer: &mut [u8]) -> i32 {\n")
				fmt.Fprintf(out, "    unsafe { raw::random_get(buffer.as_mut_ptr() as u32, buffer.len() as u32) }\n}\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn random_get(buffer: &mut [u8]) -> i32 {\n")
				fmt.Fprintf(out, "    match host::with(|host| host.random_get(buffer)) {\n")
				fmt.Fprintf(out, "        Some(status) => status,\n")
				fmt.Fprintf(out, "        None => { for byte in buffer { *byte = 0; } 0 }\n")
				fmt.Fprintf(out, "    }\n}\n\n")
			}
		case "output_write":
			if len(function.Params) == 2 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Writes visible plugin output through the host.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn output_write(data: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    unsafe { raw::output_write(data.as_ptr() as u32, data.len() as u32) }\n}\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn output_write(data: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    host::with(|host| host.output_write(data)).unwrap_or(data.len() as i32)\n}\n\n")
			}
		case "service_response_len":
			if len(function.Params) == 0 && function.Result == "u32" {
				fmt.Fprintf(out, "/// Returns the bytes the host copied in the last successful service call.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn service_response_len() -> u32 { unsafe { raw::service_response_len() } }\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn service_response_len() -> u32 {\n")
				fmt.Fprintf(out, "    host::with(|host| host.service_response_len()).unwrap_or(0)\n}\n\n")
			}
		case "language_respond", "service_respond", "provider_respond", "data_provider_respond":
			if len(function.Params) == 3 && function.Result == "i32" &&
				function.Params[1].Type == "u32" && function.Params[2].Type == "u32" {
				fmt.Fprintf(out, "/// Sends one in-flight response payload to the host.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn %s(request_id: u64, payload: &[u8]) -> i32 {\n", function.Name)
				fmt.Fprintf(out, "    unsafe { raw::%s(request_id, payload.as_ptr() as u32, payload.len() as u32) }\n}\n\n", function.Name)
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn %s(request_id: u64, payload: &[u8]) -> i32 {\n", function.Name)
				fmt.Fprintf(out, "    host::with(|host| host.%s(request_id, payload))\n", function.Name)
				fmt.Fprintf(out, "        .unwrap_or(ServiceStatus::Unavailable.code())\n}\n\n")
			}
		case "language_cancelled", "provider_cancelled", "data_provider_cancelled":
			if len(function.Params) == 1 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Reports whether the host cancelled one in-flight request.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn %s(request_id: u64) -> i32 { unsafe { raw::%s(request_id) } }\n\n",
					function.Name, function.Name)
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn %s(request_id: u64) -> i32 {\n", function.Name)
				fmt.Fprintf(out, "    host::with(|host| host.%s(request_id)).unwrap_or(0)\n}\n\n", function.Name)
			}
		case "mcp_tool_result":
			if len(function.Params) == 3 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Delivers one MCP tool result to the host.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn mcp_tool_result(request_id: u32, payload: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    unsafe { raw::mcp_tool_result(request_id, payload.as_ptr() as u32, payload.len() as u32) }\n}\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn mcp_tool_result(request_id: u32, payload: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    host::with(|host| host.mcp_tool_result(request_id, payload))\n")
				fmt.Fprintf(out, "        .unwrap_or(ServiceStatus::Unavailable.code())\n}\n\n")
			}
		case "mcp_tool_progress":
			if len(function.Params) == 4 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Delivers one MCP progress notification to the host.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn mcp_tool_progress(request_id: u32, progress: u32, message: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    unsafe { raw::mcp_tool_progress(request_id, progress, message.as_ptr() as u32, message.len() as u32) }\n}\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn mcp_tool_progress(request_id: u32, progress: u32, message: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    host::with(|host| host.mcp_tool_progress(request_id, progress, message))\n")
				fmt.Fprintf(out, "        .unwrap_or(ServiceStatus::Unavailable.code())\n}\n\n")
			}
		case "provider_input_read":
			if len(function.Params) == 3 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Reads available provider input into the buffer.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn provider_input_read(stream: u32, buffer: &mut [u8]) -> i32 {\n")
				fmt.Fprintf(out, "    unsafe { raw::provider_input_read(stream, buffer.as_mut_ptr() as u32, buffer.len() as u32) }\n}\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn provider_input_read(stream: u32, buffer: &mut [u8]) -> i32 {\n")
				fmt.Fprintf(out, "    host::with(|host| host.provider_input_read(stream, buffer)).unwrap_or(-1)\n}\n\n")
			}
		case "provider_input_credit", "provider_output_credit":
			if len(function.Params) == 1 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Returns the available credit on one provider stream direction.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn %s(stream: u32) -> i32 { unsafe { raw::%s(stream) } }\n\n",
					function.Name, function.Name)
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn %s(stream: u32) -> i32 {\n", function.Name)
				fmt.Fprintf(out, "    host::with(|host| host.%s(stream)).unwrap_or(-1)\n}\n\n", function.Name)
			}
		case "provider_output_write":
			if len(function.Params) == 3 && function.Result == "i32" {
				fmt.Fprintf(out, "/// Writes bytes to one provider stream output queue.\n")
				fmt.Fprintf(out, "#[cfg(target_arch = \"wasm32\")]\n")
				fmt.Fprintf(out, "pub fn provider_output_write(stream: u32, data: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    unsafe { raw::provider_output_write(stream, data.as_ptr() as u32, data.len() as u32) }\n}\n\n")
				fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
				fmt.Fprintf(out, "pub fn provider_output_write(stream: u32, data: &[u8]) -> i32 {\n")
				fmt.Fprintf(out, "    host::with(|host| host.provider_output_write(stream, data)).unwrap_or(-1)\n}\n\n")
			}
		}
	}
}

// writeRustHostShim emits the native-test host hook. It exists only off
// wasm32, so a real plugin carries no extra machinery and the generated file
// remains self-contained for the standalone scaffold.
func writeRustHostShim(out *strings.Builder) {
	fmt.Fprintf(out, "#[cfg(not(target_arch = \"wasm32\"))]\n")
	fmt.Fprintf(out, "/// Native-test host functions used when the bindings are compiled for a\n")
	fmt.Fprintf(out, "/// test harness instead of wasm32.\n")
	fmt.Fprintf(out, "pub mod host {\n")
	fmt.Fprintf(out, "    use std::sync::Mutex;\n\n")
	fmt.Fprintf(out, "    /// The host side of every generated import.\n")
	fmt.Fprintf(out, "    pub trait Host: Send {\n")
	fmt.Fprintf(out, "        /// Returns the host ABI version.\n")
	fmt.Fprintf(out, "        fn abi_version(&mut self) -> i32;\n")
	fmt.Fprintf(out, "        /// Receives one guest log line.\n")
	fmt.Fprintf(out, "        fn log(&mut self, level: i32, message: &[u8]);\n")
	fmt.Fprintf(out, "        /// Returns the virtual clock in Unix nanoseconds.\n")
	fmt.Fprintf(out, "        fn now_ns(&mut self) -> i64;\n")
	fmt.Fprintf(out, "        /// Fills the buffer with deterministic random bytes.\n")
	fmt.Fprintf(out, "        fn random_get(&mut self, buffer: &mut [u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Captures visible output.\n")
	fmt.Fprintf(out, "        fn output_write(&mut self, data: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Answers one host-service call and returns its transport status.\n")
	fmt.Fprintf(out, "        fn service_call(&mut self, service: &str, method_id: u32,\n")
	fmt.Fprintf(out, "                        request: &[u8], response: &mut [u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Returns the bytes copied by the last successful service call.\n")
	fmt.Fprintf(out, "        fn service_response_len(&mut self) -> u32;\n")
	fmt.Fprintf(out, "        /// Delivers one language-provider response payload.\n")
	fmt.Fprintf(out, "        fn language_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Reports whether one language call was cancelled.\n")
	fmt.Fprintf(out, "        fn language_cancelled(&mut self, request_id: u64) -> i32;\n")
	fmt.Fprintf(out, "        /// Delivers one MCP tool result payload.\n")
	fmt.Fprintf(out, "        fn mcp_tool_result(&mut self, request_id: u32, payload: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Delivers one MCP progress notification.\n")
	fmt.Fprintf(out, "        fn mcp_tool_progress(&mut self, request_id: u32, progress: u32,\n")
	fmt.Fprintf(out, "                             message: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Delivers one cross-plugin service response payload.\n")
	fmt.Fprintf(out, "        fn service_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Delivers one connection-provider response payload.\n")
	fmt.Fprintf(out, "        fn provider_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Reports whether one provider call was cancelled.\n")
	fmt.Fprintf(out, "        fn provider_cancelled(&mut self, request_id: u64) -> i32;\n")
	fmt.Fprintf(out, "        /// Reads available provider input into the buffer.\n")
	fmt.Fprintf(out, "        fn provider_input_read(&mut self, stream: u32, buffer: &mut [u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Returns the available provider input credit.\n")
	fmt.Fprintf(out, "        fn provider_input_credit(&mut self, stream: u32) -> i32;\n")
	fmt.Fprintf(out, "        /// Writes bytes to one provider output queue.\n")
	fmt.Fprintf(out, "        fn provider_output_write(&mut self, stream: u32, data: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Returns the available provider output credit.\n")
	fmt.Fprintf(out, "        fn provider_output_credit(&mut self, stream: u32) -> i32;\n")
	fmt.Fprintf(out, "        /// Delivers one data-provider response payload.\n")
	fmt.Fprintf(out, "        fn data_provider_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;\n")
	fmt.Fprintf(out, "        /// Reports whether one data-provider call was cancelled.\n")
	fmt.Fprintf(out, "        fn data_provider_cancelled(&mut self, request_id: u64) -> i32;\n")
	fmt.Fprintf(out, "    }\n\n")
	fmt.Fprintf(out, "    static INSTALLED: Mutex<Option<Box<dyn Host>>> = Mutex::new(None);\n\n")
	fmt.Fprintf(out, "    /// Installs the host used by native bindings and returns the previous\n")
	fmt.Fprintf(out, "    /// one, if any.\n")
	fmt.Fprintf(out, "    pub fn install(host: Box<dyn Host>) -> Option<Box<dyn Host>> {\n")
	fmt.Fprintf(out, "        let mut slot = INSTALLED.lock().unwrap_or_else(|poisoned| poisoned.into_inner());\n")
	fmt.Fprintf(out, "        slot.replace(host)\n    }\n\n")
	fmt.Fprintf(out, "    /// Removes the installed host.\n")
	fmt.Fprintf(out, "    pub fn uninstall() -> Option<Box<dyn Host>> {\n")
	fmt.Fprintf(out, "        let mut slot = INSTALLED.lock().unwrap_or_else(|poisoned| poisoned.into_inner());\n")
	fmt.Fprintf(out, "        slot.take()\n    }\n\n")
	fmt.Fprintf(out, "    /// Runs the closure with the installed host. Host methods must not\n")
	fmt.Fprintf(out, "    /// re-enter this function.\n")
	fmt.Fprintf(out, "    pub fn with<T>(f: impl FnOnce(&mut dyn Host) -> T) -> Option<T> {\n")
	fmt.Fprintf(out, "        let mut slot = INSTALLED.lock().unwrap_or_else(|poisoned| poisoned.into_inner());\n")
	fmt.Fprintf(out, "        slot.as_mut().map(|host| f(host.as_mut()))\n")
	fmt.Fprintf(out, "    }\n}\n\n")
}

func rustEnumBase(base string) string {
	if base == "i64" {
		return "i64"
	}
	return "i32"
}

func goCamel(name string) string {
	var out strings.Builder
	for _, part := range strings.FieldsFunc(name, func(r rune) bool {
		return r == '_' || r == '-' || r == '.'
	}) {
		switch strings.ToLower(part) {
		case "abi":
			out.WriteString("ABI")
		case "id":
			out.WriteString("ID")
		default:
			if part == "" {
				continue
			}
			out.WriteString(strings.ToUpper(part[:1]))
			out.WriteString(part[1:])
		}
	}
	return out.String()
}

func rustConstSuffix(name string) string {
	var out strings.Builder
	for _, r := range name {
		switch {
		case r >= 'a' && r <= 'z':
			out.WriteRune(r - 'a' + 'A')
		case r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
			out.WriteRune(r)
		default:
			out.WriteByte('_')
		}
	}
	return out.String()
}
